CREATE TABLE tbl_pa_airports ("airport_identifier" VarChar(4) NOT NULL,"airport_name" VarChar(30) NOT NULL,"airport_ref_latitude" Float NOT NULL,"airport_ref_longitude" Float NOT NULL,"airport_type" VarChar(1) NOT NULL,"area_code" VarChar(3) NOT NULL,"ata_iata_code" VarChar(3) DEFAULT NULL,"city" VarChar(24) DEFAULT NULL,"continent" VarChar(40) DEFAULT NULL,"country_3letter" VarChar(3) DEFAULT NULL,"country" VarChar(40) DEFAULT NULL,"elevation" Int DEFAULT NULL,"fuel" VarChar(14) DEFAULT NULL,"icao_code" VarChar(2) NOT NULL,"ifr_capability" VarChar(1) DEFAULT NULL,"longest_runway_surface_code" VarChar(1) NOT NULL,"magnetic_variation" Real DEFAULT NULL,"speed_limit_altitude" VarChar(5) DEFAULT NULL,"speed_limit" SmallInt DEFAULT NULL,"state_2letter" VarChar(2) DEFAULT NULL,"state" VarChar(50) DEFAULT NULL,"time_zone" VarChar(3) DEFAULT NULL,"transition_altitude" Int DEFAULT NULL,"transition_level" Int DEFAULT NULL, id TEXT);
CREATE TABLE tbl_pg_runways ("airport_identifier" VarChar(4) NOT NULL,"area_code" VarChar(3) DEFAULT NULL,"displaced_threshold_distance" SmallInt DEFAULT NULL,"icao_code" VarChar(2) DEFAULT NULL,"landing_threshold_elevation" Int DEFAULT NULL,"llz_identifier" VarChar(4) DEFAULT NULL,"llz_mls_gls_category" VarChar(1) DEFAULT NULL,"part_time_lights" VarChar(1) DEFAULT NULL,"runway_gradient" Real DEFAULT NULL,"runway_identifier" VarChar(3) NOT NULL,"runway_latitude" Float DEFAULT NULL,"runway_length" Real NOT NULL,"runway_lights" VarChar(1) DEFAULT NULL,"runway_longitude" Float DEFAULT NULL,"runway_magnetic_bearing" Real DEFAULT NULL,"runway_true_bearing" Real DEFAULT NULL,"runway_width" SmallInt NOT NULL,"surface_code" VarChar(3) DEFAULT NULL,"threshold_crossing_height" Int DEFAULT NULL,"traffic_pattern_altitude" Int DEFAULT NULL,"traffic_pattern" VarChar(1) DEFAULT NULL, id TEXT);
