entifier_id TEXT, recommended_navaid_id TEXT, center_waypoint_id TEXT);
CREATE TABLE ps_runtime_waypoints (
    id TEXT PRIMARY KEY,
    identifier TEXT NOT NULL,
    latitude REAL NOT NULL,
    longitude REAL NOT NULL,
    navaid_id TEXT
